CREATE OR REPLACE FUNCTION public.academy_set_mark(p_item_id text, p_status text, p_user_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare target uuid:=coalesce(p_user_id,auth.uid());
begin
 if not academy_private.is_active() or not (target=auth.uid() or academy_private.can_manage(target)) then raise exception 'Forbidden'; end if;
 if target=auth.uid() and not academy_private.can_read_content(p_item_id) then raise exception 'Content unavailable'; end if;
 if not exists(select 1 from public.academy_content where id=p_item_id and kind='menu') then raise exception 'Invalid menu item'; end if;
 insert into public.academy_menu_marks(user_id,item_id,status) values(target,p_item_id,p_status)
 on conflict(user_id,item_id) do update set status=excluded.status,updated_at=now();
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'menu_mark',target::text,jsonb_build_object('item_id',p_item_id,'status',p_status));
end $function$

CREATE OR REPLACE FUNCTION public.academy_start_test(p_test_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.academy_content; a uuid; k jsonb;
begin
 if not academy_private.can_read_content(p_test_id) then raise exception 'Forbidden'; end if;
 select * into c from public.academy_content where id=p_test_id and kind='test';
 select keys into k from academy_private.test_keys where test_id=p_test_id;
 if c.id is null or k is null then raise exception 'Test unavailable'; end if;
 -- A fresh immutable snapshot keeps editing from changing a running attempt.
 insert into public.academy_attempts(user_id,test_id,snapshot) values(auth.uid(),p_test_id,c.payload) returning id into a;
 insert into academy_private.attempt_keys(attempt_id,keys) values(a,k);
 return jsonb_build_object('attempt_id',a,'title',c.title,'questions',c.payload->'questions','time_limit_seconds',c.payload->'timeLimitSeconds','started_at',now());
end $function$

CREATE OR REPLACE FUNCTION public.academy_save_content(p_document jsonb, p_keys jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old public.academy_content; rid text:=p_document->>'restaurant_id'; dep text:=p_document->>'department';
begin
 if not academy_private.can_edit(rid,dep) then raise exception 'Forbidden'; end if;
 select * into old from public.academy_content where id=p_document->>'id';
 if old.id is not null and not academy_private.can_edit(old.restaurant_id,old.department) then raise exception 'Forbidden'; end if;
 -- Keys must never enter the exposed payload, including nested fields.
 if jsonb_path_exists(p_document->'payload','$.**.correct') or jsonb_path_exists(p_document->'payload','$.**.key_snapshot') then raise exception 'Keep answer keys private'; end if;
 insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department)
 values(p_document->>'id',p_document->>'kind',p_document->>'title',p_document->>'course_id',p_document->'payload',coalesce((p_document->>'published')::boolean,true),rid,dep)
 on conflict(id) do update set title=excluded.title,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department,updated_at=now();
 if p_keys is not null then
 if p_document->>'kind'<>'test' or jsonb_typeof(p_keys)<>'object' then raise exception 'Invalid test keys'; end if;
 insert into academy_private.test_keys(test_id,keys) values(p_document->>'id',p_keys) on conflict(test_id) do update set keys=excluded.keys;
 end if;
 insert into academy_private.audit_log(actor_id,action,target) values(auth.uid(),'content_save',p_document->>'id');
end $function$

CREATE OR REPLACE FUNCTION public.academy_review_attempt(p_attempt_id uuid, p_manual_score integer, p_feedback text DEFAULT ''::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.academy_attempts; manual_count integer; k jsonb;
begin
 select * into a from public.academy_attempts where id=p_attempt_id for update;
 if a.id is null or not academy_private.can_manage(a.user_id) then raise exception 'Forbidden'; end if;
 if a.submitted_at is null or not a.needs_review then raise exception 'Not awaiting review'; end if;
 select keys into k from academy_private.attempt_keys where attempt_id=a.id;
 select count(*) into manual_count from jsonb_array_elements(a.snapshot->'questions') q where q->>'type'='text' or k->(q->>'id') is null;
 if p_manual_score<0 or p_manual_score>manual_count or p_manual_score is null then raise exception 'Invalid manual score'; end if;
 update public.academy_attempts set score=score+p_manual_score,needs_review=false,
 passed=(score+p_manual_score>=coalesce((snapshot->>'passCount')::integer,total)) and
 (coalesce((snapshot->>'timeLimitSeconds')::integer,0)=0 or submitted_at<=started_at+make_interval(secs=>(snapshot->>'timeLimitSeconds')::integer+10)),
 reviewed_by=auth.uid(),reviewed_at=now(),feedback=left(p_feedback,5000) where id=p_attempt_id;
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'review_attempt',p_attempt_id::text,jsonb_build_object('manual_score',p_manual_score));
end $function$

CREATE OR REPLACE FUNCTION public.academy_submit_test(p_attempt_id uuid, p_answers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.academy_attempts; k jsonb; q jsonb; expected jsonb; supplied jsonb; points integer:=0; n integer:=0; review boolean:=false; ok boolean; deadline integer; timed_out boolean;
begin
 if not academy_private.is_active() then raise exception 'Forbidden'; end if;
 select * into a from public.academy_attempts where id=p_attempt_id and user_id=auth.uid() for update;
 if a.id is null then raise exception 'Attempt unavailable'; end if;
 if a.submitted_at is not null then return jsonb_build_object('score',a.score,'total',a.total,'passed',a.passed,'needs_review',a.needs_review,'timed_out',coalesce((a.snapshot->>'timeLimitSeconds')::integer,0)>0 and a.submitted_at>a.started_at+make_interval(secs=>coalesce((a.snapshot->>'timeLimitSeconds')::integer,0)+10)); end if;
 if jsonb_typeof(p_answers)<>'object' or octet_length(p_answers::text)>100000 then raise exception 'Invalid answers'; end if;
 select keys into k from academy_private.attempt_keys where attempt_id=a.id;
 for q in select value from jsonb_array_elements(a.snapshot->'questions') loop
 n:=n+1; expected:=k->(q->>'id'); supplied:=p_answers->(q->>'id');
 if q->>'type'='text' or expected is null then review:=true;
 elsif jsonb_typeof(supplied)='array' then
 select coalesce(jsonb_agg(value order by value), '[]'::jsonb) into supplied from (select distinct value from jsonb_array_elements(supplied)) s;
 select coalesce(jsonb_agg(value order by value), '[]'::jsonb) into expected from (select distinct value from jsonb_array_elements(expected)) e;
 if supplied=expected then points:=points+1; end if;
 end if;
 end loop;
 deadline:=coalesce((a.snapshot->>'timeLimitSeconds')::integer,0);
 ok:=not review and points>=coalesce((a.snapshot->>'passCount')::integer,n);
 timed_out:=deadline>0 and now()>a.started_at+make_interval(secs=>deadline+10); if timed_out then ok:=false; end if;
 update public.academy_attempts set submitted_at=now(),score=points,total=n,passed=ok,needs_review=review,answers=p_answers where id=a.id;
 return jsonb_build_object('score',points,'total',n,'passed',ok,'needs_review',review,'timed_out',timed_out);
end $function$

CREATE OR REPLACE FUNCTION public.academy_reserve_material_file(p_material_id text, p_filename text, p_mime_type text, p_byte_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.academy_content; f public.academy_material_files; ext text; file_id uuid:=gen_random_uuid();
begin
 select * into c from public.academy_content where id=p_material_id and kind='material' for update;
 if c.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Forbidden'; end if;
 ext:=case p_mime_type when 'application/pdf' then 'pdf' when 'image/jpeg' then 'jpg' when 'image/png' then 'png'
 when 'image/webp' then 'webp' when 'image/gif' then 'gif' when 'video/mp4' then 'mp4' when 'video/webm' then 'webm' end;
 if ext is null or p_byte_size is null or p_byte_size<=0 or p_byte_size>52428800 then raise exception 'Unsupported file or size limit'; end if;
 if p_filename is null or length(trim(p_filename))=0 or length(p_filename)>240 then raise exception 'Invalid filename'; end if;
 if (select count(*) from public.academy_material_files where material_id=c.id and status<>'archived')>=10 then raise exception 'Maximum 10 files per material'; end if;
 insert into public.academy_material_files(id,material_id,storage_path,filename,mime_type,byte_size,uploaded_by)
 values(file_id,c.id,c.id||'/'||file_id::text||'.'||ext,left(regexp_replace(p_filename,'[[:cntrl:]]','','g'),200),p_mime_type,p_byte_size,auth.uid()) returning * into f;
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'material_file_reserve',f.id::text,jsonb_build_object('material_id',c.id));
 return to_jsonb(f);
end $function$

CREATE OR REPLACE FUNCTION public.academy_finish_material_file(p_file_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f public.academy_material_files; c public.academy_content; object_meta jsonb;
begin
 select * into f from public.academy_material_files where id=p_file_id for update;
 select * into c from public.academy_content where id=f.material_id and kind='material';
 if f.id is null or c.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Forbidden'; end if;
 select metadata into object_meta from storage.objects where bucket_id='academy-materials' and name=f.storage_path;
 if object_meta is null or (object_meta->>'size')::bigint is distinct from f.byte_size
 or object_meta->>'mimetype' is distinct from f.mime_type then raise exception 'Upload not complete or file metadata mismatch'; end if;
 update public.academy_material_files set status='ready',updated_at=now() where id=f.id returning * into f;
 insert into academy_private.audit_log(actor_id,action,target) values(auth.uid(),'material_file_ready',f.id::text);
 return to_jsonb(f);
end $function$

CREATE OR REPLACE FUNCTION public.academy_archive_material_file(p_file_id uuid, p_archived boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f public.academy_material_files; c public.academy_content;
begin
 select * into f from public.academy_material_files where id=p_file_id for update;
 select * into c from public.academy_content where id=f.material_id and kind='material';
 if f.id is null or c.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Forbidden'; end if;
 if p_archived is distinct from true then perform public.academy_finish_material_file(f.id);
 else update public.academy_material_files set status='archived',updated_at=now() where id=f.id; end if;
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'material_file_archive',f.id::text,jsonb_build_object('archived',p_archived));
end $function$

CREATE OR REPLACE FUNCTION public.academy_update_profile(p_user_id uuid, p_full_name text, p_birth_date date DEFAULT NULL::date, p_gender text DEFAULT NULL::text, p_team_joined_on date DEFAULT NULL::date, p_avatar_data text DEFAULT NULL::text)
 RETURNS academy_profiles
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result public.academy_profiles;
begin
 if not academy_private.is_active() or not (p_user_id=auth.uid() or academy_private.can_manage(p_user_id)) then raise exception 'Forbidden'; end if;
 if length(trim(p_full_name)) not between 2 and 100 then raise exception 'Укажите имя и фамилию (2–100 символов).'; end if;
 if p_birth_date>current_date or p_birth_date<date '1900-01-01' then raise exception 'Проверьте дату рождения.'; end if;
 if p_gender is not null and p_gender not in ('female','male','unspecified') then raise exception 'Проверьте значение пола.'; end if;
 if p_team_joined_on>current_date or p_team_joined_on<date '1900-01-01' then raise exception 'Проверьте дату вступления.'; end if;
 if p_avatar_data is not null and (length(p_avatar_data)>180000 or p_avatar_data !~ '^data:image/jpeg;base64,[A-Za-z0-9+/=]+$') then raise exception 'Выберите фото JPG, PNG или WebP.'; end if;
 update public.academy_profiles set full_name=trim(p_full_name),birth_date=p_birth_date,gender=p_gender,
 team_joined_on=p_team_joined_on,avatar_data=p_avatar_data,updated_at=now() where id=p_user_id returning * into result;
 if result.id is null then raise exception 'Профиль не найден.'; end if;
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'update_profile',p_user_id::text,'{"fields":["full_name","birth_date","gender","team_joined_on","avatar_data"]}'::jsonb);
 return result;
end $function$

CREATE OR REPLACE FUNCTION public.academy_set_priority(p_content_id text, p_priority text, p_lesson_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.academy_content; updated_payload jsonb;
begin
 select * into c from public.academy_content where id=p_content_id for update;
 if c.id is null or c.kind not in ('course','test') or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Forbidden'; end if;
 if p_priority not in ('start','attestation','additional') then raise exception 'Неверный приоритет.'; end if;
 if p_lesson_id is null then updated_payload=jsonb_set(c.payload,'{priority}',to_jsonb(p_priority));
 else
 if not exists(select 1 from jsonb_array_elements(c.payload->'lessons') l where l->>'id'=p_lesson_id) then raise exception 'Урок не найден.'; end if;
 updated_payload=jsonb_set(c.payload,'{lessons}',(select jsonb_agg(case when l->>'id'=p_lesson_id then jsonb_set(l,'{priority}',to_jsonb(p_priority)) else l end order by n) from jsonb_array_elements(c.payload->'lessons') with ordinality a(l,n)));
 end if;
 update public.academy_content set payload=updated_payload,updated_at=now() where id=c.id;
 insert into academy_private.audit_log(actor_id,action,target,details) values(auth.uid(),'set_priority',c.id,jsonb_build_object('priority',p_priority,'lesson_id',p_lesson_id));
end $function$

CREATE OR REPLACE FUNCTION public.academy_course_editor(p_course_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.academy_content;d academy_private.course_drafts;
begin
 select * into c from public.academy_content where id=p_course_id and kind='course';
 if c.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Курс недоступен для редактирования.';end if;
 select * into d from academy_private.course_drafts where course_id=c.id;
 return jsonb_build_object('document',coalesce(d.document,to_jsonb(c)),'live_updated_at',c.updated_at,'draft_updated_at',d.updated_at,'has_draft',d.course_id is not null,'conflict',d.course_id is not null and d.base_updated_at is distinct from c.updated_at);
end $function$

CREATE OR REPLACE FUNCTION public.academy_reserve_course_media(p_course_id text, p_filename text, p_mime_type text, p_byte_size bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.academy_content;m public.academy_course_media;ext text;uid uuid:=gen_random_uuid();
begin
 select * into c from public.academy_content where id=p_course_id and kind='course' for update;
 if c.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Нет доступа к изображениям курса.';end if;
 ext:=case p_mime_type when 'image/jpeg' then 'jpg' when 'image/png' then 'png' when 'image/webp' then 'webp' when 'image/gif' then 'gif' when 'video/mp4' then 'mp4' when 'video/webm' then 'webm' when 'application/pdf' then 'pdf' end;
 if ext is null or p_byte_size is null or p_byte_size not between 1 and 52428800 or nullif(trim(p_filename),'') is null or length(p_filename)>240 then raise exception 'Поддерживаются изображения, PDF и видео до 50 МБ.';end if;
 if (select count(*) from public.academy_course_media where course_id=c.id)>=300 then raise exception 'В курсе уже 300 вложений.';end if;
 insert into public.academy_course_media(id,course_id,storage_path,filename,mime_type,byte_size,uploaded_by) values(uid,c.id,c.id||'/'||uid||'.'||ext,p_filename,p_mime_type,p_byte_size,auth.uid()) returning * into m;return to_jsonb(m);
end $function$

CREATE OR REPLACE FUNCTION public.academy_finish_course_media(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m public.academy_course_media;c public.academy_content;meta jsonb;
begin
 select * into m from public.academy_course_media where id=p_id for update;select * into c from public.academy_content where id=m.course_id;
 if m.id is null or not academy_private.can_edit(c.restaurant_id,c.department) then raise exception 'Нет доступа к файлу.';end if;
 select metadata into meta from storage.objects where bucket_id='academy-course-media' and name=m.storage_path;
 if meta is null or (meta->>'size')::bigint is distinct from m.byte_size or meta->>'mimetype' is distinct from m.mime_type then raise exception 'Загрузка не завершена.';end if;
 update public.academy_course_media set status='ready' where id=m.id returning * into m;return to_jsonb(m);
end $function$

CREATE OR REPLACE FUNCTION public.academy_save_menu(p_document jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.academy_profiles; old public.academy_content; proposed public.academy_content;
begin
 select * into actor from public.academy_profiles where id=auth.uid() and status='active';
 if actor.id is null or actor.role not in ('admin','manager') or p_document->>'kind' is distinct from 'menu' then raise exception 'Forbidden'; end if;
 if nullif(trim(p_document->>'title'),'') is null or nullif(p_document->>'id','') is null then raise exception 'Complete menu title'; end if;
 if jsonb_typeof(p_document->'payload') is distinct from 'object' or octet_length((p_document->'payload')::text)>100000 then raise exception 'Invalid menu card'; end if;
 if coalesce(p_document->'payload'->>'menuSection','') not in ('bar','kitchen') then raise exception 'Invalid menu section'; end if;
 proposed:=jsonb_populate_record(null::public.academy_content,p_document);
 select * into old from public.academy_content where id=proposed.id;
 if old.id is not null and old.kind<>'menu' then raise exception 'Content type cannot change'; end if;
 if not academy_private.can_edit_menu_for(actor,proposed) or
 (old.id is not null and not academy_private.can_edit_menu_for(actor,old)) then raise exception 'Menu outside administrator scope'; end if;
 if actor.role='manager' and not actor.operations_director then
 if old.id is not null and (old.restaurant_id is distinct from proposed.restaurant_id or
 old.payload->>'brand' is distinct from proposed.payload->>'brand' or
 old.payload->>'menuSection' is distinct from proposed.payload->>'menuSection') then raise exception 'Menu scope cannot change'; end if;
 proposed.department:=null;
 end if;
 insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department)
 values(proposed.id,'menu',trim(proposed.title),null,proposed.payload,coalesce(proposed.published,false),proposed.restaurant_id,proposed.department)
 on conflict(id) do update set title=excluded.title,payload=excluded.payload,published=excluded.published,
 restaurant_id=excluded.restaurant_id,department=excluded.department,updated_at=now();
 insert into academy_private.audit_log(actor_id,action,target) values(auth.uid(),'menu_save',proposed.id);
end $function$

CREATE OR REPLACE FUNCTION public.academy_cancel_work_change(p_request_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not academy_private.is_active() then raise exception 'Доступ закрыт.'; end if;
 update public.academy_work_changes set status='cancelled',reviewed_at=now(),reviewed_by=auth.uid() where id=p_request_id and user_id=auth.uid() and status='pending';
 if not found then raise exception 'Заявка уже обработана или недоступна.'; end if;
 insert into academy_private.audit_log(actor_id,action,target) values(auth.uid(),'cancel_work_change',p_request_id::text);
end $function$

CREATE OR REPLACE FUNCTION public.academy_request_work_change(p_restaurant_id text, p_department text, p_position text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.academy_profiles; request_id uuid;
begin
 select * into actor from public.academy_profiles where id=auth.uid() and status='active' for update;
 if actor.id is null then raise exception 'Доступ закрыт.'; end if;
 if not academy_private.valid_work(p_restaurant_id,p_department,p_position) then raise exception 'Проверьте заведение, подразделение и должность.'; end if;
 if actor.restaurant_id is not distinct from p_restaurant_id and actor.department is not distinct from p_department and actor.position is not distinct from p_position then raise exception 'Выберите новые рабочие данные.'; end if;
 if exists(select 1 from public.academy_work_changes where user_id=actor.id and status='pending') then raise exception 'Сначала дождитесь решения или отмените текущую заявку.'; end if;
 insert into public.academy_work_changes(user_id,full_name,original_role,from_restaurant,from_department,from_position,restaurant_id,department,position)
 values(actor.id,actor.full_name,actor.role,actor.restaurant_id,actor.department,actor.position,p_restaurant_id,p_department,p_position) returning id into request_id;
 insert into academy_private.audit_log(actor_id,action,target,details) values(actor.id,'request_work_change',request_id::text,jsonb_build_object('user_id',actor.id,'restaurant',p_restaurant_id,'department',p_department,'position',p_position));
 return request_id;
end $function$

CREATE OR REPLACE FUNCTION public.academy_review_work_change(p_request_id uuid, p_approve boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.academy_profiles; member public.academy_profiles; request public.academy_work_changes; target_user uuid;
begin
 select * into actor from public.academy_profiles where id=auth.uid() and status='active';
 if actor.id is null or actor.role not in ('manager','admin') or p_approve is null then raise exception 'Доступ закрыт.'; end if;
 select user_id into target_user from public.academy_work_changes where id=p_request_id;
 select * into member from public.academy_profiles where id=target_user for update;
 select * into request from public.academy_work_changes where id=p_request_id for update;
 if request.id is null or request.status<>'pending' then raise exception 'Заявка уже обработана или недоступна.'; end if;
 if member.id=actor.id or not(actor.role='admin' or actor.operations_director and academy_private.can_manage(member.id) or (actor.role='manager' and member.role='employee' and request.original_role='employee' and actor.restaurant_id=request.restaurant_id and actor.department=request.department)) then raise exception 'Подтверждение доступно администратору принимающей команды или владельцу.'; end if;
 if member.status<>'active' or member.role is distinct from request.original_role or member.restaurant_id is distinct from request.from_restaurant or member.department is distinct from request.from_department or member.position is distinct from request.from_position then raise exception 'Рабочие данные уже изменились. Попросите сотрудника отменить заявку и отправить новую.'; end if;
 if p_approve then
 update public.academy_profiles set restaurant_id=request.restaurant_id,department=request.department,position=request.position,updated_at=now() where id=member.id;
 end if;
 update public.academy_work_changes set status=case when p_approve then 'approved' else 'rejected' end,reviewed_at=now(),reviewed_by=actor.id where id=request.id;
 insert into academy_private.audit_log(actor_id,action,target,details) values(actor.id,'review_work_change',request.id::text,jsonb_build_object('approved',p_approve,'user_id',member.id,'from',jsonb_build_object('restaurant',member.restaurant_id,'department',member.department,'position',member.position),'to',jsonb_build_object('restaurant',request.restaurant_id,'department',request.department,'position',request.position)));
end $function$

CREATE OR REPLACE FUNCTION public.academy_assign_work(p_user_id uuid, p_restaurant_id text, p_department text, p_position text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare actor public.academy_profiles; member public.academy_profiles;
begin
 select * into actor from public.academy_profiles where id=auth.uid() and status='active';
 select * into member from public.academy_profiles where id=p_user_id for update;
 if actor.id is null or member.id is null or not academy_private.can_manage(p_user_id) or (actor.role<>'admin' and not actor.operations_director and (member.id=actor.id or member.role<>'employee')) then raise exception 'Можно менять только рабочие данные сотрудников своей команды.'; end if;
 if not academy_private.valid_work(p_restaurant_id,p_department,p_position) then raise exception 'Проверьте заведение, подразделение и должность.'; end if;
 update public.academy_profiles set restaurant_id=p_restaurant_id,department=p_department,position=p_position,updated_at=now() where id=member.id;
 update public.academy_work_changes set status='cancelled',reviewed_at=now(),reviewed_by=actor.id where user_id=member.id and status='pending';
 insert into academy_private.audit_log(actor_id,action,target,details) values(actor.id,'assign_work',member.id::text,jsonb_build_object('from',jsonb_build_object('restaurant',member.restaurant_id,'department',member.department,'position',member.position),'to',jsonb_build_object('restaurant',p_restaurant_id,'department',p_department,'position',p_position)));
end $function$

CREATE OR REPLACE FUNCTION academy_private.normalize_training_level()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.department='Руководитель' or new.department is null then new.training_level:=null;
 elsif new.position='Официант' then new.training_level:=case when academy_private.waiter_is_certified(new.id,new.restaurant_id,new.department,new.position) then 'certified' else 'trainee' end;
 elsif new.training_level is null then new.training_level:='trainee';end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.academy_set_training_level(p_user_id uuid, p_level text)
